package com.bank.tenancy.quota;

import org.springframework.stereotype.Component;
import lombok.extern.slf4j.Slf4j;

@Component
@Slf4j
public class QuotaManager {

    // Apply per-client produce/consume byte-rate quotas. The broker DELAYS
    // over-quota requests (back-pressure) rather than dropping messages.
    public void applyQuota(String clientId, long produceBytesPerSec, long consumeBytesPerSec) {
        // Equivalent to: kafka-configs --alter --entity-type clients --entity-name <clientId>
        //   --add-config producer_byte_rate=..,consumer_byte_rate=..
        log.info("Quota set for client {}: produce={} B/s consume={} B/s (throttle, no drop)",
                clientId, produceBytesPerSec, consumeBytesPerSec);
    }
}
