// ─── File: demo/NoisyNeighborDemo.java ───
package com.bank.tenancy.demo;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class NoisyNeighborDemo {

    private static final Logger log = Logger.getLogger(NoisyNeighborDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        Cluster cluster = new Cluster(/*sharedBandwidthMBps*/ 60);

        Tenant retail = new Tenant("retail", 20);     // wants 20 MB/s
        Tenant corporate = new Tenant("corporate", 100); // spikes: wants 100 MB/s
        Tenant cards = new Tenant("cards", 15);        // critical

        log.info("=== Before: no quotas, shared bandwidth (noisy neighbor) ===");
        cluster.distributeWithoutQuota(List.of(retail, corporate, cards), log);

        log.info("=== After: per-client quotas throttle the spiker without dropping ===");
        QuotaEnforcer enforcer = new QuotaEnforcer();
        enforcer.setQuota("retail", 20);
        enforcer.setQuota("corporate", 10);  // cap the batchy tenant
        enforcer.setQuota("cards", 15);
        cluster.distributeWithQuota(List.of(retail, corporate, cards), enforcer, log);

        log.info("=== Critical tenant 'cards' on a dedicated broker group ===");
        cluster.dedicateBrokerGroup("cards", log);

        log.info("=== Consumer group isolation ===");
        ConsumerGroupIsolation.demonstrate(log);
    }
}

// ─── Would be in Tenant.java in a real project ───
class Tenant {
    final String name; final int demandMBps;
    Tenant(String name, int demandMBps) { this.name = name; this.demandMBps = demandMBps; }
}

// ─── Would be in QuotaEnforcer.java in a real project ───
class QuotaEnforcer {
    private final java.util.Map<String, Integer> quotas = new java.util.HashMap<>();
    void setQuota(String tenant, int mbps) { quotas.put(tenant, mbps); }
    int allowed(Tenant t) { return Math.min(t.demandMBps, quotas.getOrDefault(t.name, Integer.MAX_VALUE)); }
}

// ─── Would be in Cluster.java in a real project ───
class Cluster {
    private final int sharedBandwidthMBps;
    Cluster(int sharedBandwidthMBps) { this.sharedBandwidthMBps = sharedBandwidthMBps; }

    void distributeWithoutQuota(List<Tenant> tenants, Logger log) {
        int totalDemand = tenants.stream().mapToInt(t -> t.demandMBps).sum();
        for (Tenant t : tenants) {
            // Proportional starvation: the spiker grabs most of the pipe.
            int got = sharedBandwidthMBps * t.demandMBps / totalDemand;
            if (got < t.demandMBps && !t.name.equals("corporate")) {
                log.severe(t.name + " STARVED: wanted " + t.demandMBps + " MB/s, got " + got + " MB/s");
            } else {
                log.info(t.name + " got " + got + " MB/s (wanted " + t.demandMBps + ")");
            }
        }
    }

    void distributeWithQuota(List<Tenant> tenants, QuotaEnforcer enforcer, Logger log) {
        for (Tenant t : tenants) {
            int capped = enforcer.allowed(t);
            if (capped < t.demandMBps)
                log.info(t.name + " throttled to quota " + capped + " MB/s (messages delayed, NOT dropped)");
            else
                log.info(t.name + " served " + capped + " MB/s within quota");
        }
        log.info("All tenants fit within shared bandwidth; no starvation");
    }

    void dedicateBrokerGroup(String tenant, Logger log) {
        log.info("Pinned " + tenant + " partitions to dedicated broker group (resource isolation)");
    }
}

// ─── Would be in ConsumerGroupIsolation.java in a real project ───
class ConsumerGroupIsolation {
    static void demonstrate(Logger log) {
        log.info("retail-group offset=10500 (healthy)");
        log.warning("corporate-group offset=2000 lag=80000 (slow consumer)");
        log.info("Because offsets are per-group, corporate's lag does NOT block retail-group");
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("[%1$tF %1$tT] [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
